//  To parse this JSON data, first install
//
//      json.hpp  https://github.com/nlohmann/json
//
//  Then include this file, and then do
//
//     TopLevel data = nlohmann::json::parse(jsonString);
//     Scores data = nlohmann::json::parse(jsonString);
//     Names data = nlohmann::json::parse(jsonString);
//     Alias data = nlohmann::json::parse(jsonString);
//     Choice data = nlohmann::json::parse(jsonString);

#pragma once

#include <optional>
#include <variant>
#include "json.hpp"

#include <optional>
#include <stdexcept>
#include <regex>
#include <algorithm>
#include <unordered_map>

#ifndef NLOHMANN_OPT_HELPER
#define NLOHMANN_OPT_HELPER
namespace nlohmann {
    template <typename T>
    struct adl_serializer<std::shared_ptr<T>> {
        static void to_json(json & j, const std::shared_ptr<T> & opt) {
            if (!opt) j = nullptr; else j = *opt;
        }

        static std::shared_ptr<T> from_json(const json & j) {
            if (j.is_null()) return std::shared_ptr<T>(); else return std::make_shared<T>(j.get<T>());
        }
    };
    template <typename T>
    struct adl_serializer<std::optional<T>> {
        static void to_json(json & j, const std::optional<T> & opt) {
            if (!opt) j = nullptr; else j = *opt;
        }

        static std::optional<T> from_json(const json & j) {
            if (j.is_null()) return std::optional<T>(); else return std::make_optional<T>(j.get<T>());
        }
    };
}
#endif

namespace quicktype {
    using nlohmann::json;

    class ClassMemberConstraints {
        private:
        std::optional<int64_t> min_int_value;
        std::optional<int64_t> max_int_value;
        std::optional<double> min_double_value;
        std::optional<double> max_double_value;
        std::optional<size_t> min_length;
        std::optional<size_t> max_length;
        std::optional<std::string> pattern;

        public:
        ClassMemberConstraints(
            std::optional<int64_t> min_int_value,
            std::optional<int64_t> max_int_value,
            std::optional<double> min_double_value,
            std::optional<double> max_double_value,
            std::optional<size_t> min_length,
            std::optional<size_t> max_length,
            std::optional<std::string> pattern
        ) : min_int_value(min_int_value), max_int_value(max_int_value), min_double_value(min_double_value), max_double_value(max_double_value), min_length(min_length), max_length(max_length), pattern(pattern) {}
        ClassMemberConstraints() = default;
        virtual ~ClassMemberConstraints() = default;

        void set_min_int_value(int64_t min_int_value) { this->min_int_value = min_int_value; }
        auto get_min_int_value() const { return min_int_value; }

        void set_max_int_value(int64_t max_int_value) { this->max_int_value = max_int_value; }
        auto get_max_int_value() const { return max_int_value; }

        void set_min_double_value(double min_double_value) { this->min_double_value = min_double_value; }
        auto get_min_double_value() const { return min_double_value; }

        void set_max_double_value(double max_double_value) { this->max_double_value = max_double_value; }
        auto get_max_double_value() const { return max_double_value; }

        void set_min_length(size_t min_length) { this->min_length = min_length; }
        auto get_min_length() const { return min_length; }

        void set_max_length(size_t max_length) { this->max_length = max_length; }
        auto get_max_length() const { return max_length; }

        void set_pattern(const std::string &  pattern) { this->pattern = pattern; }
        auto get_pattern() const { return pattern; }
    };

    class ClassMemberConstraintException : public std::runtime_error {
        public:
        ClassMemberConstraintException(const std::string &  msg) : std::runtime_error(msg) {}
    };

    class ValueTooLowException : public ClassMemberConstraintException {
        public:
        ValueTooLowException(const std::string &  msg) : ClassMemberConstraintException(msg) {}
    };

    class ValueTooHighException : public ClassMemberConstraintException {
        public:
        ValueTooHighException(const std::string &  msg) : ClassMemberConstraintException(msg) {}
    };

    class ValueTooShortException : public ClassMemberConstraintException {
        public:
        ValueTooShortException(const std::string &  msg) : ClassMemberConstraintException(msg) {}
    };

    class ValueTooLongException : public ClassMemberConstraintException {
        public:
        ValueTooLongException(const std::string &  msg) : ClassMemberConstraintException(msg) {}
    };

    class InvalidPatternException : public ClassMemberConstraintException {
        public:
        InvalidPatternException(const std::string &  msg) : ClassMemberConstraintException(msg) {}
    };

    inline void CheckConstraint(const std::string &  name, const ClassMemberConstraints & c, int64_t value) {
        if (c.get_min_int_value() != std::nullopt && value < *c.get_min_int_value()) {
            throw ValueTooLowException ("Value too low for " + name + " (" + std::to_string(value) + "<" + std::to_string(*c.get_min_int_value()) + ")");
        }

        if (c.get_max_int_value() != std::nullopt && value > *c.get_max_int_value()) {
            throw ValueTooHighException ("Value too high for " + name + " (" + std::to_string(value) + ">" + std::to_string(*c.get_max_int_value()) + ")");
        }
    }

    inline void CheckConstraint(const std::string &  name, const ClassMemberConstraints & c, const std::optional<int64_t> & value) {
        if (value) {
            CheckConstraint(name, c, *value);
        }
    }

    inline void CheckConstraint(const std::string &  name, const ClassMemberConstraints & c, double value) {
        if (c.get_min_double_value() != std::nullopt && value < *c.get_min_double_value()) {
            throw ValueTooLowException ("Value too low for " + name + " (" + std::to_string(value) + "<" + std::to_string(*c.get_min_double_value()) + ")");
        }

        if (c.get_max_double_value() != std::nullopt && value > *c.get_max_double_value()) {
            throw ValueTooHighException ("Value too high for " + name + " (" + std::to_string(value) + ">" + std::to_string(*c.get_max_double_value()) + ")");
        }
    }

    inline void CheckConstraint(const std::string &  name, const ClassMemberConstraints & c, const std::optional<double> & value) {
        if (value) {
            CheckConstraint(name, c, *value);
        }
    }

    inline size_t CodePointLength(const std::string &  value) {
        return std::count_if(value.begin(), value.end(), [](char ch) { return (static_cast<unsigned char>(ch) & 0xC0) != 0x80; });
    }

    inline void CheckConstraint(const std::string &  name, const ClassMemberConstraints & c, const std::string &  value) {
        if (c.get_min_length() != std::nullopt && CodePointLength(value) < *c.get_min_length()) {
            throw ValueTooShortException ("Value too short for " + name + " (" + std::to_string(CodePointLength(value)) + "<" + std::to_string(*c.get_min_length()) + ")");
        }

        if (c.get_max_length() != std::nullopt && CodePointLength(value) > *c.get_max_length()) {
            throw ValueTooLongException ("Value too long for " + name + " (" + std::to_string(CodePointLength(value)) + ">" + std::to_string(*c.get_max_length()) + ")");
        }

        if (c.get_pattern() != std::nullopt) {
            std::smatch result;
            std::regex_search(value, result, std::regex( *c.get_pattern() ));
            if (result.empty()) {
                throw InvalidPatternException ("Value doesn't match pattern for " + name + " (" + value +" != " + *c.get_pattern() + ")");
            }
        }
    }

    inline void CheckConstraint(const std::string &  name, const ClassMemberConstraints & c, const std::optional<std::string> & value) {
        if (value) {
            CheckConstraint(name, c, *value);
        }
    }

    #ifndef NLOHMANN_UNTYPED_quicktype_HELPER
    #define NLOHMANN_UNTYPED_quicktype_HELPER
    inline json get_untyped(const json & j, const char * property) {
        if (j.find(property) != j.end()) {
            return j.at(property).get<json>();
        }
        return json();
    }

    inline json get_untyped(const json & j, std::string property) {
        return get_untyped(j, property.data());
    }
    #endif

    #ifndef NLOHMANN_OPTIONAL_quicktype_HELPER
    #define NLOHMANN_OPTIONAL_quicktype_HELPER
    template <typename T>
    inline std::shared_ptr<T> get_heap_optional(const json & j, const char * property) {
        auto it = j.find(property);
        if (it != j.end() && !it->is_null()) {
            return j.at(property).get<std::shared_ptr<T>>();
        }
        return std::shared_ptr<T>();
    }

    template <typename T>
    inline std::shared_ptr<T> get_heap_optional(const json & j, std::string property) {
        return get_heap_optional<T>(j, property.data());
    }
    template <typename T>
    inline std::optional<T> get_stack_optional(const json & j, const char * property) {
        auto it = j.find(property);
        if (it != j.end() && !it->is_null()) {
            return j.at(property).get<std::optional<T>>();
        }
        return std::optional<T>();
    }

    template <typename T>
    inline std::optional<T> get_stack_optional(const json & j, std::string property) {
        return get_stack_optional<T>(j, property.data());
    }
    #endif

    struct MaybeRec;
    struct Rec;

    enum class BigKind : int { C0, C1, C2, C3, C4, C5, C6, C7, C8, C9, C10, C11, C12, C13, C14, C15, C16 };

    using ChoiceUnion = std::variant<bool, double, int64_t, std::string>;

    enum class Kind : int { ONE = 1, TWO = 20, NUL };

    using Choice = std::optional<std::variant<int64_t, std::string>>;

    enum class MaybeKind : int { A, B };

    struct MaybeRec : std::shared_ptr<std::variant<std::map<std::string, MaybeRec>, std::string>> {
        using base = std::shared_ptr<std::variant<std::map<std::string, MaybeRec>, std::string>>;
        using base::base;
        using base::operator=;
    };

    using MixedMap = std::variant<std::vector<std::string>, int64_t>;

    class Node {
        public:
        Node() = default;
        virtual ~Node() = default;

        private:
        std::optional<std::vector<Node>> children;
        std::shared_ptr<Node> next;
        std::string value;

        public:
        const std::optional<std::vector<Node>> & get_children() const { return children; }
        std::optional<std::vector<Node>> & get_mutable_children() { return children; }
        void set_children(const std::optional<std::vector<Node>> & value) { this->children = value; }

        const std::shared_ptr<Node> & get_next() const { return next; }
        std::shared_ptr<Node> & get_mutable_next() { return next; }
        void set_next(const std::shared_ptr<Node> & value) { this->next = value; }

        const std::string & get_value() const { return value; }
        std::string & get_mutable_value() { return value; }
        void set_value(const std::string & value) { this->value = value; }
    };

    struct Rec : std::variant<std::vector<Rec>, int64_t> {
        using base = std::variant<std::vector<Rec>, int64_t>;
        using base::base;
        using base::operator=;
    };

    /**
     * The top level, with a trailing backslash \.
     */
    class TopLevel {
        public:
        TopLevel() :
            name_constraint(std::nullopt, std::nullopt, std::nullopt, std::nullopt, 1, 3, std::string("^[a-z\"\\\\]+$")),
            opt_name_constraint(std::nullopt, std::nullopt, std::nullopt, std::nullopt, std::nullopt, std::nullopt, std::string("^x")),
            ratio_constraint(std::nullopt, std::nullopt, 0.5, 1e+21, std::nullopt, std::nullopt, std::nullopt),
            small_constraint(-5, 100, std::nullopt, std::nullopt, std::nullopt, std::nullopt, std::nullopt)
        {}
        virtual ~TopLevel() = default;

        private:
        nlohmann::json anything;
        BigKind big_kind = BigKind::C3;
        ChoiceUnion choice;
        std::map<std::string, int64_t> counts;
        bool flag = true;
        std::string id;
        Kind kind = Kind::TWO;
        Choice maybe_choice;
        std::optional<MaybeKind> maybe_kind;
        MaybeRec maybe_rec;
        std::optional<int64_t> maybe_small;
        std::map<std::string, MixedMap> mixed_map;
        std::string name = ([] { constexpr auto &s = "a\u0000b"; return std::string(s, sizeof(s) / sizeof(s[0]) - 1); }());
        ClassMemberConstraints name_constraint;
        Node node;
        nlohmann::json nothing;
        int64_t nul_key;
        nlohmann::json opt_anything;
        std::optional<std::string> opt_name;
        ClassMemberConstraints opt_name_constraint;
        std::shared_ptr<Node> opt_node;
        nlohmann::json opt_nothing;
        std::shared_ptr<Rec> opt_rec;
        std::optional<std::string> opt_when;
        double ratio;
        ClassMemberConstraints ratio_constraint;
        Rec rec;
        int64_t small = 7;
        ClassMemberConstraints small_constraint;
        std::vector<std::string> tags;
        std::string when;

        public:
        const nlohmann::json & get_anything() const { return anything; }
        nlohmann::json & get_mutable_anything() { return anything; }
        void set_anything(const nlohmann::json & value) { this->anything = value; }

        const BigKind & get_big_kind() const { return big_kind; }
        BigKind & get_mutable_big_kind() { return big_kind; }
        void set_big_kind(const BigKind & value) { this->big_kind = value; }

        const ChoiceUnion & get_choice() const { return choice; }
        ChoiceUnion & get_mutable_choice() { return choice; }
        void set_choice(const ChoiceUnion & value) { this->choice = value; }

        const std::map<std::string, int64_t> & get_counts() const { return counts; }
        std::map<std::string, int64_t> & get_mutable_counts() { return counts; }
        void set_counts(const std::map<std::string, int64_t> & value) { this->counts = value; }

        const bool & get_flag() const { return flag; }
        bool & get_mutable_flag() { return flag; }
        void set_flag(const bool & value) { this->flag = value; }

        const std::string & get_id() const { return id; }
        std::string & get_mutable_id() { return id; }
        void set_id(const std::string & value) { this->id = value; }

        const Kind & get_kind() const { return kind; }
        Kind & get_mutable_kind() { return kind; }
        void set_kind(const Kind & value) { this->kind = value; }

        Choice get_maybe_choice() const { return maybe_choice; }
        void set_maybe_choice(Choice value) { this->maybe_choice = value; }

        std::optional<MaybeKind> get_maybe_kind() const { return maybe_kind; }
        void set_maybe_kind(std::optional<MaybeKind> value) { this->maybe_kind = value; }

        MaybeRec get_maybe_rec() const { return maybe_rec; }
        void set_maybe_rec(MaybeRec value) { this->maybe_rec = value; }

        std::optional<int64_t> get_maybe_small() const { return maybe_small; }
        void set_maybe_small(std::optional<int64_t> value) { this->maybe_small = value; }

        const std::map<std::string, MixedMap> & get_mixed_map() const { return mixed_map; }
        std::map<std::string, MixedMap> & get_mutable_mixed_map() { return mixed_map; }
        void set_mixed_map(const std::map<std::string, MixedMap> & value) { this->mixed_map = value; }

        const std::string & get_name() const { return name; }
        std::string & get_mutable_name() { return name; }
        void set_name(const std::string & value) { CheckConstraint("name", name_constraint, value); this->name = value; }

        const Node & get_node() const { return node; }
        Node & get_mutable_node() { return node; }
        void set_node(const Node & value) { this->node = value; }

        const nlohmann::json & get_nothing() const { return nothing; }
        nlohmann::json & get_mutable_nothing() { return nothing; }
        void set_nothing(const nlohmann::json & value) { this->nothing = value; }

        const int64_t & get_nul_key() const { return nul_key; }
        int64_t & get_mutable_nul_key() { return nul_key; }
        void set_nul_key(const int64_t & value) { this->nul_key = value; }

        const nlohmann::json & get_opt_anything() const { return opt_anything; }
        nlohmann::json & get_mutable_opt_anything() { return opt_anything; }
        void set_opt_anything(const nlohmann::json & value) { this->opt_anything = value; }

        const std::optional<std::string> & get_opt_name() const { return opt_name; }
        std::optional<std::string> & get_mutable_opt_name() { return opt_name; }
        void set_opt_name(const std::optional<std::string> & value) { CheckConstraint("opt_name", opt_name_constraint, value); this->opt_name = value; }

        const std::shared_ptr<Node> & get_opt_node() const { return opt_node; }
        std::shared_ptr<Node> & get_mutable_opt_node() { return opt_node; }
        void set_opt_node(const std::shared_ptr<Node> & value) { this->opt_node = value; }

        const nlohmann::json & get_opt_nothing() const { return opt_nothing; }
        nlohmann::json & get_mutable_opt_nothing() { return opt_nothing; }
        void set_opt_nothing(const nlohmann::json & value) { this->opt_nothing = value; }

        const std::shared_ptr<Rec> & get_opt_rec() const { return opt_rec; }
        std::shared_ptr<Rec> & get_mutable_opt_rec() { return opt_rec; }
        void set_opt_rec(const std::shared_ptr<Rec> & value) { this->opt_rec = value; }

        const std::optional<std::string> & get_opt_when() const { return opt_when; }
        std::optional<std::string> & get_mutable_opt_when() { return opt_when; }
        void set_opt_when(const std::optional<std::string> & value) { this->opt_when = value; }

        const double & get_ratio() const { return ratio; }
        double & get_mutable_ratio() { return ratio; }
        void set_ratio(const double & value) { CheckConstraint("ratio", ratio_constraint, value); this->ratio = value; }

        const Rec & get_rec() const { return rec; }
        Rec & get_mutable_rec() { return rec; }
        void set_rec(const Rec & value) { this->rec = value; }

        const int64_t & get_small() const { return small; }
        int64_t & get_mutable_small() { return small; }
        void set_small(const int64_t & value) { CheckConstraint("small", small_constraint, value); this->small = value; }

        const std::vector<std::string> & get_tags() const { return tags; }
        std::vector<std::string> & get_mutable_tags() { return tags; }
        void set_tags(const std::vector<std::string> & value) { this->tags = value; }

        const std::string & get_when() const { return when; }
        std::string & get_mutable_when() { return when; }
        void set_when(const std::string & value) { this->when = value; }
    };

    using Scores = std::map<std::string, double>;
    using Names = std::vector<std::string>;
    using Alias = std::string;
}

namespace quicktype {
void from_json(const json & j, Node & x);
void to_json(json & j, const Node & x);

void from_json(const json & j, TopLevel & x);
void to_json(json & j, const TopLevel & x);

void from_json(const json & j, BigKind & x);
void to_json(json & j, const BigKind & x);

void from_json(const json & j, Kind & x);
void to_json(json & j, const Kind & x);

void from_json(const json & j, MaybeKind & x);
void to_json(json & j, const MaybeKind & x);

void from_json(const json & j, MaybeRec & x);
void to_json(json & j, const MaybeRec & x);

void from_json(const json & j, Rec & x);
void to_json(json & j, const Rec & x);
}
namespace nlohmann {
template <>
struct adl_serializer<std::variant<bool, double, int64_t, std::string>> {
    static void from_json(const json & j, std::variant<bool, double, int64_t, std::string> & x);
    static void to_json(json & j, const std::variant<bool, double, int64_t, std::string> & x);
};

template <>
struct adl_serializer<std::variant<int64_t, std::string>> {
    static void from_json(const json & j, std::variant<int64_t, std::string> & x);
    static void to_json(json & j, const std::variant<int64_t, std::string> & x);
};

template <>
struct adl_serializer<std::variant<std::map<std::string, quicktype::MaybeRec>, std::string>> {
    static void from_json(const json & j, std::variant<std::map<std::string, quicktype::MaybeRec>, std::string> & x);
    static void to_json(json & j, const std::variant<std::map<std::string, quicktype::MaybeRec>, std::string> & x);
};

template <>
struct adl_serializer<std::variant<std::vector<std::string>, int64_t>> {
    static void from_json(const json & j, std::variant<std::vector<std::string>, int64_t> & x);
    static void to_json(json & j, const std::variant<std::vector<std::string>, int64_t> & x);
};

template <>
struct adl_serializer<std::variant<std::vector<quicktype::Rec>, int64_t>> {
    static void from_json(const json & j, std::variant<std::vector<quicktype::Rec>, int64_t> & x);
    static void to_json(json & j, const std::variant<std::vector<quicktype::Rec>, int64_t> & x);
};
}
namespace quicktype {
    inline void from_json(const json & j, Node& x) {
        if (!j.is_object()) throw std::runtime_error("Expected object");
        if (j.find("children") != j.end() && j.at("children").is_null()) throw std::runtime_error("Unexpected null");
        x.set_children(get_stack_optional<std::vector<Node>>(j, "children"));
        if (j.find("next") != j.end() && j.at("next").is_null()) throw std::runtime_error("Unexpected null");
        x.set_next(get_heap_optional<Node>(j, "next"));
        x.set_value(j.at("value").get<std::string>());
    }

    inline void to_json(json & j, const Node & x) {
        j = json::object();
        j["children"] = x.get_children();
        j["next"] = x.get_next();
        j["value"] = x.get_value();
    }

    inline void from_json(const json & j, TopLevel& x) {
        if (!j.is_object()) throw std::runtime_error("Expected object");
        x.set_anything(get_untyped(j, "anything"));
        x.set_big_kind(j.at("bigKind").get<BigKind>());
        x.set_choice(j.at("choice").get<ChoiceUnion>());
        x.set_counts(j.at("counts").get<std::map<std::string, int64_t>>());
        x.set_flag(j.at("flag").get<bool>());
        if (j.find("id") != j.end() && !std::regex_match(j.at("id").get<std::string>(), std::regex("^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$"))) throw std::runtime_error("Expected UUID");
        x.set_id(j.at("id").get<std::string>());
        x.set_kind(j.at("kind").get<Kind>());
        j.at("maybeChoice");
        x.set_maybe_choice(get_stack_optional<std::variant<int64_t, std::string>>(j, "maybeChoice"));
        j.at("maybeKind");
        x.set_maybe_kind(get_stack_optional<MaybeKind>(j, "maybeKind"));
        j.at("maybeRec");
        x.set_maybe_rec(get_heap_optional<MaybeRec>(j, "maybeRec"));
        j.at("maybeSmall");
        x.set_maybe_small(get_stack_optional<int64_t>(j, "maybeSmall"));
        x.set_mixed_map(j.at("mixedMap").get<std::map<std::string, MixedMap>>());
        x.set_name(j.at("name").get<std::string>());
        x.set_node(j.at("node").get<Node>());
        x.set_nothing(get_untyped(j, "nothing"));
        if (j.find(([] { constexpr auto &s = "nul\u0000key"; return std::string(s, sizeof(s) / sizeof(s[0]) - 1); }())) != j.end() && !j.at(([] { constexpr auto &s = "nul\u0000key"; return std::string(s, sizeof(s) / sizeof(s[0]) - 1); }())).is_number_integer()) throw std::runtime_error("Expected integer");
        x.set_nul_key(j.at(([] { constexpr auto &s = "nul\u0000key"; return std::string(s, sizeof(s) / sizeof(s[0]) - 1); }())).get<int64_t>());
        x.set_opt_anything(get_untyped(j, "optAnything"));
        if (j.find("optName") != j.end() && j.at("optName").is_null()) throw std::runtime_error("Unexpected null");
        x.set_opt_name(get_stack_optional<std::string>(j, "optName"));
        if (j.find("optNode") != j.end() && j.at("optNode").is_null()) throw std::runtime_error("Unexpected null");
