namespace nlohmann {
    template <typename T>
    struct adl_serializer<std::shared_ptr<T>> {
        static void to_json(json & j, const std::shared_ptr<T> & opt) {
            if (!opt) j = nullptr; else j = *opt;
        }

        static std::shared_ptr<T> from_json(const json & j) {
            if (j.is_null()) return std::shared_ptr<T>(); else return std::make_shared<T>(j.get<T>());
        }
    };
    template <typename T>
    struct adl_serializer<std::optional<T>> {
        static void to_json(json & j, const std::optional<T> & opt) {
            if (!opt) j = nullptr; else j = *opt;
        }

        static std::optional<T> from_json(const json & j) {
            if (j.is_null()) return std::optional<T>(); else return std::make_optional<T>(j.get<T>());
        }
    };
}
#endif

namespace quicktype {
    using nlohmann::json;

    #ifndef NLOHMANN_UNTYPED_quicktype_HELPER
    #define NLOHMANN_UNTYPED_quicktype_HELPER
    inline json get_untyped(const json & j, const char * property) {
        if (j.find(property) != j.end()) {
            return j.at(property).get<json>();
        }
        return json();
    }

    inline json get_untyped(const json & j, std::string property) {
        return get_untyped(j, property.data());
    }
    #endif

    #ifndef NLOHMANN_OPTIONAL_quicktype_HELPER
    #define NLOHMANN_OPTIONAL_quicktype_HELPER
    template <typename T>
    inline std::shared_ptr<T> get_heap_optional(const json & j, const char * property) {
        auto it = j.find(property);
        if (it != j.end() && !it->is_null()) {
            return j.at(property).get<std::shared_ptr<T>>();
        }
        return std::shared_ptr<T>();
    }

    template <typename T>
    inline std::shared_ptr<T> get_heap_optional(const json & j, std::string property) {
        return get_heap_optional<T>(j, property.data());
    }
    template <typename T>
    inline std::optional<T> get_stack_optional(const json & j, const char * property) {
        auto it = j.find(property);
        if (it != j.end() && !it->is_null()) {
            return j.at(property).get<std::optional<T>>();
        }
        return std::optional<T>();
    }

    template <typename T>
    inline std::optional<T> get_stack_optional(const json & j, std::string property) {
        return get_stack_optional<T>(j, property.data());
    }
    #endif

    struct MaybeRec;
    struct Rec;

    enum class BigKind : int { C0, C1, C2, C3, C4, C5, C6, C7, C8, C9, C10, C11, C12, C13, C14, C15, C16 };

    using ChoiceUnion = std::variant<bool, double, int64_t, std::string>;

    enum class Kind : int { ONE = 1, TWO = 20, NUL };

    using Choice = std::optional<std::variant<int64_t, std::string>>;

    enum class MaybeKind : int { A, B };

    struct MaybeRec : std::shared_ptr<std::variant<std::map<std::string, MaybeRec>, std::string>> {
        using base = std::shared_ptr<std::variant<std::map<std::string, MaybeRec>, std::string>>;
        using base::base;
        using base::operator=;
    };

    using MixedMap = std::variant<std::vector<std::string>, int64_t>;

    struct Node {
        std::optional<std::vector<Node>> children;
        std::shared_ptr<Node> next;
        std::string value;
    };

    struct Rec : std::variant<std::vector<Rec>, int64_t> {
        using base = std::variant<std::vector<Rec>, int64_t>;
        using base::base;
        using base::operator=;
    };

    /**
     * The top level, with a trailing backslash \.
     */
    struct TopLevel {
        nlohmann::json anything;
        BigKind big_kind = BigKind::C3;
        ChoiceUnion choice;
        std::map<std::string, int64_t> counts;
        bool flag = true;
        std::string id;
        Kind kind = Kind::TWO;
        Choice maybe_choice;
        std::optional<MaybeKind> maybe_kind;
        MaybeRec maybe_rec;
        std::optional<int64_t> maybe_small;
        std::map<std::string, MixedMap> mixed_map;
        std::string name = ([] { constexpr auto &s = "a\u0000b"; return std::string(s, sizeof(s) / sizeof(s[0]) - 1); }());
        Node node;
        nlohmann::json nothing;
        int64_t nul_key;
        nlohmann::json opt_anything;
        std::optional<std::string> opt_name;
        std::shared_ptr<Node> opt_node;
        nlohmann::json opt_nothing;
        std::shared_ptr<Rec> opt_rec;
        std::optional<std::string> opt_when;
        double ratio;
        Rec rec;
        int64_t small = 7;
        std::vector<std::string> tags;
        std::string when;
    };

    using Scores = std::map<std::string, double>;
    using Names = std::vector<std::string>;
    using Alias = std::string;
}

