namespace quicktype {
    inline void from_json(const json & j, Node& x) {
        if (!j.is_object()) throw std::runtime_error("Expected object");
        if (j.find("children") != j.end() && j.at("children").is_null()) throw std::runtime_error("Unexpected null");
        x.children = get_stack_optional<std::vector<Node>>(j, "children");
        if (j.find("next") != j.end() && j.at("next").is_null()) throw std::runtime_error("Unexpected null");
        x.next = get_heap_optional<Node>(j, "next");
        x.value = j.at("value").get<std::string>();
    }

    inline void to_json(json & j, const Node & x) {
        j = json::object();
        j["children"] = x.children;
        j["next"] = x.next;
        j["value"] = x.value;
    }

    inline void from_json(const json & j, TopLevel& x) {
        if (!j.is_object()) throw std::runtime_error("Expected object");
        x.anything = get_untyped(j, "anything");
        x.big_kind = j.at("bigKind").get<BigKind>();
        x.choice = j.at("choice").get<ChoiceUnion>();
        x.counts = j.at("counts").get<std::map<std::string, int64_t>>();
        x.flag = j.at("flag").get<bool>();
        if (j.find("id") != j.end() && !std::regex_match(j.at("id").get<std::string>(), std::regex("^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$"))) throw std::runtime_error("Expected UUID");
        x.id = j.at("id").get<std::string>();
        x.kind = j.at("kind").get<Kind>();
        j.at("maybeChoice");
        x.maybe_choice = get_stack_optional<std::variant<int64_t, std::string>>(j, "maybeChoice");
        j.at("maybeKind");
        x.maybe_kind = get_stack_optional<MaybeKind>(j, "maybeKind");
        j.at("maybeRec");
        x.maybe_rec = get_heap_optional<MaybeRec>(j, "maybeRec");
        j.at("maybeSmall");
        x.maybe_small = get_stack_optional<int64_t>(j, "maybeSmall");
        x.mixed_map = j.at("mixedMap").get<std::map<std::string, MixedMap>>();
        x.name = j.at("name").get<std::string>();
        x.node = j.at("node").get<Node>();
        x.nothing = get_untyped(j, "nothing");
        if (j.find(([] { constexpr auto &s = "nul\u0000key"; return std::string(s, sizeof(s) / sizeof(s[0]) - 1); }())) != j.end() && !j.at(([] { constexpr auto &s = "nul\u0000key"; return std::string(s, sizeof(s) / sizeof(s[0]) - 1); }())).is_number_integer()) throw std::runtime_error("Expected integer");
        x.nul_key = j.at(([] { constexpr auto &s = "nul\u0000key"; return std::string(s, sizeof(s) / sizeof(s[0]) - 1); }())).get<int64_t>();
        x.opt_anything = get_untyped(j, "optAnything");
        if (j.find("optName") != j.end() && j.at("optName").is_null()) throw std::runtime_error("Unexpected null");
        x.opt_name = get_stack_optional<std::string>(j, "optName");
        if (j.find("optNode") != j.end() && j.at("optNode").is_null()) throw std::runtime_error("Unexpected null");
        x.opt_node = get_heap_optional<Node>(j, "optNode");
        x.opt_nothing = get_untyped(j, "optNothing");
        if (j.find("optRec") != j.end() && j.at("optRec").is_null()) throw std::runtime_error("Unexpected null");
        x.opt_rec = get_heap_optional<Rec>(j, "optRec");
        if (j.find("optWhen") != j.end() && !std::regex_match(j.at("optWhen").get<std::string>(), std::regex("^[0-9]{4}-[0-9]{2}-[0-9]{2}T.*$"))) throw std::runtime_error("Expected date-time");
        if (j.find("optWhen") != j.end() && j.at("optWhen").is_null()) throw std::runtime_error("Unexpected null");
        x.opt_when = get_stack_optional<std::string>(j, "optWhen");
        x.ratio = j.at("ratio").get<double>();
        x.rec = j.at("rec").get<Rec>();
        if (j.find("small") != j.end() && !j.at("small").is_number_integer()) throw std::runtime_error("Expected integer");
        x.small = j.at("small").get<int64_t>();
        if (j.at("tags").size() < 1) throw std::runtime_error("Too few items");
        if (j.at("tags").size() > 4) throw std::runtime_error("Too many items");
        x.tags = j.at("tags").get<std::vector<std::string>>();
        if (j.find("when") != j.end() && !std::regex_match(j.at("when").get<std::string>(), std::regex("^[0-9]{4}-[0-9]{2}-[0-9]{2}T.*$"))) throw std::runtime_error("Expected date-time");
        x.when = j.at("when").get<std::string>();
    }

    inline void to_json(json & j, const TopLevel & x) {
        j = json::object();
        j["anything"] = x.anything;
        j["bigKind"] = x.big_kind;
        j["choice"] = x.choice;
        j["counts"] = x.counts;
        j["flag"] = x.flag;
        j["id"] = x.id;
        j["kind"] = x.kind;
        j["maybeChoice"] = x.maybe_choice;
        j["maybeKind"] = x.maybe_kind;
        j["maybeRec"] = x.maybe_rec;
        j["maybeSmall"] = x.maybe_small;
        j["mixedMap"] = x.mixed_map;
        j["name"] = x.name;
        j["node"] = x.node;
        j["nothing"] = x.nothing;
        j[([] { constexpr auto &s = "nul\u0000key"; return std::string(s, sizeof(s) / sizeof(s[0]) - 1); }())] = x.nul_key;
        j["optAnything"] = x.opt_anything;
        j["optName"] = x.opt_name;
        j["optNode"] = x.opt_node;
        j["optNothing"] = x.opt_nothing;
        j["optRec"] = x.opt_rec;
        j["optWhen"] = x.opt_when;
        j["ratio"] = x.ratio;
        j["rec"] = x.rec;
        j["small"] = x.small;
        j["tags"] = x.tags;
        j["when"] = x.when;
    }

    inline void from_json(const json & j, BigKind & x) {
        static std::unordered_map<std::string, BigKind> enumValues {
            {"c0", BigKind::C0},
            {"c1", BigKind::C1},
            {"c2", BigKind::C2},
            {"c3", BigKind::C3},
            {"c4", BigKind::C4},
            {"c5", BigKind::C5},
            {"c6", BigKind::C6},
            {"c7", BigKind::C7},
            {"c8", BigKind::C8},
            {"c9", BigKind::C9},
            {"c10", BigKind::C10},
            {"c11", BigKind::C11},
            {"c12", BigKind::C12},
            {"c13", BigKind::C13},
            {"c14", BigKind::C14},
            {"c15", BigKind::C15},
            {"c16", BigKind::C16},
        };
        auto iter = enumValues.find(j.get<std::string>());
        if (iter != enumValues.end()) {
            x = iter->second;
        }
        else { throw std::runtime_error("Cannot deserialize to enumeration \"BigKind\""); }
    }

    inline void to_json(json & j, const BigKind & x) {
        switch (x) {
            case BigKind::C0: j = "c0"; break;
            case BigKind::C1: j = "c1"; break;
            case BigKind::C2: j = "c2"; break;
            case BigKind::C3: j = "c3"; break;
            case BigKind::C4: j = "c4"; break;
            case BigKind::C5: j = "c5"; break;
            case BigKind::C6: j = "c6"; break;
            case BigKind::C7: j = "c7"; break;
            case BigKind::C8: j = "c8"; break;
            case BigKind::C9: j = "c9"; break;
            case BigKind::C10: j = "c10"; break;
            case BigKind::C11: j = "c11"; break;
            case BigKind::C12: j = "c12"; break;
            case BigKind::C13: j = "c13"; break;
            case BigKind::C14: j = "c14"; break;
            case BigKind::C15: j = "c15"; break;
            case BigKind::C16: j = "c16"; break;
            default: throw std::runtime_error("Unexpected value in enumeration \"BigKind\": " + std::to_string(static_cast<int>(x)));
        }
    }

    inline void from_json(const json & j, Kind & x) {
        if (j == "one") x = Kind::ONE;
        else if (j == "two") x = Kind::TWO;
        else if (j == ([] { constexpr auto &s = "nul\u0000"; return std::string(s, sizeof(s) / sizeof(s[0]) - 1); }())) x = Kind::NUL;
        else { throw std::runtime_error("Cannot deserialize to enumeration \"Kind\""); }
    }

    inline void to_json(json & j, const Kind & x) {
        switch (x) {
            case Kind::ONE: j = "one"; break;
            case Kind::TWO: j = "two"; break;
            case Kind::NUL: j = ([] { constexpr auto &s = "nul\u0000"; return std::string(s, sizeof(s) / sizeof(s[0]) - 1); }()); break;
            default: throw std::runtime_error("Unexpected value in enumeration \"Kind\": " + std::to_string(static_cast<int>(x)));
        }
    }

    inline void from_json(const json & j, MaybeKind & x) {
        if (j == "a") x = MaybeKind::A;
        else if (j == "b") x = MaybeKind::B;
        else { throw std::runtime_error("Cannot deserialize to enumeration \"MaybeKind\""); }
    }

    inline void to_json(json & j, const MaybeKind & x) {
        switch (x) {
            case MaybeKind::A: j = "a"; break;
            case MaybeKind::B: j = "b"; break;
            default: throw std::runtime_error("Unexpected value in enumeration \"MaybeKind\": " + std::to_string(static_cast<int>(x)));
        }
    }

    inline void from_json(const json & j, MaybeRec & x) {
        x = j.get<MaybeRec::base>();
    }

    inline void to_json(json & j, const MaybeRec & x) {
        j = static_cast<const MaybeRec::base &>(x);
    }

    inline void from_json(const json & j, Rec & x) {
        x = j.get<Rec::base>();
    }

    inline void to_json(json & j, const Rec & x) {
        j = static_cast<const Rec::base &>(x);
    }
