    inline void from_json(const json & j, Node& x) {
        if (!j.is_object()) throw std::runtime_error("Expected object");
        if (j.find("children") != j.end() && j.at("children").is_null()) throw std::runtime_error("Unexpected null");
        x.set_children(get_stack_optional<std::vector<Node>>(j, Utf16_Utf8<std::wstring, std::string>::convert(L"children")));
        if (j.find("next") != j.end() && j.at("next").is_null()) throw std::runtime_error("Unexpected null");
        x.set_next(get_heap_optional<Node>(j, Utf16_Utf8<std::wstring, std::string>::convert(L"next")));
        x.set_value(Utf16_Utf8<std::string, std::wstring>::convert(j.at(Utf16_Utf8<std::wstring, std::string>::convert(L"value")).get<std::string>()));
    }

    inline void to_json(json & j, const Node & x) {
        j = json::object();
        j[Utf16_Utf8<std::wstring, std::string>::convert(L"children")] = x.get_children();
        j[Utf16_Utf8<std::wstring, std::string>::convert(L"next")] = x.get_next();
        j[Utf16_Utf8<std::wstring, std::string>::convert(L"value")] = Utf16_Utf8<std::wstring, std::string>::convert(x.get_value());
    }

    inline void from_json(const json & j, TopLevel& x) {
        if (!j.is_object()) throw std::runtime_error("Expected object");
        x.set_anything(get_untyped(j, Utf16_Utf8<std::wstring, std::string>::convert(L"anything")));
