    struct MaybeRec;
    struct Rec;

    enum class BigKind : int { C0, C1, C2, C3, C4, C5, C6, C7, C8, C9, C10, C11, C12, C13, C14, C15, C16 };

    using ChoiceUnion = std::variant<bool, double, int64_t, std::wstring>;

    enum class Kind : int { ONE = 1, TWO = 20, NUL };

    using Choice = std::optional<std::variant<int64_t, std::wstring>>;

    enum class MaybeKind : int { A, B };

    struct MaybeRec : std::shared_ptr<std::variant<std::map<std::wstring, MaybeRec>, std::wstring>> {
        using base = std::shared_ptr<std::variant<std::map<std::wstring, MaybeRec>, std::wstring>>;
        using base::base;
        using base::operator=;
    };

    using MixedMap = std::variant<std::vector<std::wstring>, int64_t>;

    struct Node {
        std::optional<std::vector<Node>> children;
        std::shared_ptr<Node> next;
        std::wstring value;
    };

    struct Rec : std::variant<std::vector<Rec>, int64_t> {
        using base = std::variant<std::vector<Rec>, int64_t>;
        using base::base;
        using base::operator=;
    };

    /**
     * The top level, with a trailing backslash \.
     */
    struct TopLevel {
        nlohmann::json anything;
        BigKind big_kind = BigKind::C3;
        ChoiceUnion choice;
        std::map<std::wstring, int64_t> counts;
        bool flag = true;
        std::wstring id;
        Kind kind = Kind::TWO;
        Choice maybe_choice;
        std::optional<MaybeKind> maybe_kind;
        MaybeRec maybe_rec;
        std::optional<int64_t> maybe_small;
        std::map<std::wstring, MixedMap> mixed_map;
        std::wstring name = ([] { constexpr auto &s = L"a\u0000b"; return std::wstring(s, sizeof(s) / sizeof(s[0]) - 1); }());
        Node node;
        nlohmann::json nothing;
        int64_t nul_key;
        nlohmann::json opt_anything;
        std::optional<std::wstring> opt_name;
        std::shared_ptr<Node> opt_node;
        nlohmann::json opt_nothing;
        std::shared_ptr<Rec> opt_rec;
        std::optional<std::wstring> opt_when;
        double ratio;
        Rec rec;
        int64_t small = 7;
        std::vector<std::wstring> tags;
        std::wstring when;
    };

    using Scores = std::map<std::wstring, double>;
    using Names = std::vector<std::wstring>;
    using Alias = std::wstring;
}

