    inline void from_json(json const & j, Node& x) {
        if (!j.is_object()) throw std::runtime_error("Expected object");
        if (j.find("children") != j.end() && j.at("children").is_null()) throw std::runtime_error("Unexpected null");
        x.children = get_stack_optional<std::vector<Node>>(j, Utf16_Utf8<std::wstring, std::string>::convert(L"children"));
        if (j.find("next") != j.end() && j.at("next").is_null()) throw std::runtime_error("Unexpected null");
        x.next = get_heap_optional<Node>(j, Utf16_Utf8<std::wstring, std::string>::convert(L"next"));
        x.value = Utf16_Utf8<std::string, std::wstring>::convert(j.at(Utf16_Utf8<std::wstring, std::string>::convert(L"value")).get<std::string>());
    }

    inline void to_json(json & j, Node const & x) {
        j = json::object();
        j[Utf16_Utf8<std::wstring, std::string>::convert(L"children")] = x.children;
        j[Utf16_Utf8<std::wstring, std::string>::convert(L"next")] = x.next;
        j[Utf16_Utf8<std::wstring, std::string>::convert(L"value")] = Utf16_Utf8<std::wstring, std::string>::convert(x.value);
    }

    inline void from_json(json const & j, TopLevel& x) {
        if (!j.is_object()) throw std::runtime_error("Expected object");
        x.anything = get_untyped(j, Utf16_Utf8<std::wstring, std::string>::convert(L"anything"));
        x.big_kind = j.at(Utf16_Utf8<std::wstring, std::string>::convert(L"bigKind")).get<BigKind>();
        x.choice = j.at(Utf16_Utf8<std::wstring, std::string>::convert(L"choice")).get<ChoiceUnion>();
        x.counts = Utf16_Utf8<std::map<std::string, int64_t>, std::map<std::wstring, int64_t>>::convert(j.at(Utf16_Utf8<std::wstring, std::string>::convert(L"counts")).get<std::map<std::string, int64_t>>());
        x.flag = j.at(Utf16_Utf8<std::wstring, std::string>::convert(L"flag")).get<bool>();
        if (j.find("id") != j.end() && !std::regex_match(j.at("id").get<std::string>(), std::regex("^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$"))) throw std::runtime_error("Expected UUID");
        x.id = j.at(Utf16_Utf8<std::wstring, std::string>::convert(L"id")).get<std::wstring>();
        x.kind = j.at(Utf16_Utf8<std::wstring, std::string>::convert(L"kind")).get<Kind>();
        j.at("maybeChoice");
        x.maybe_choice = get_stack_optional<std::variant<int64_t, std::wstring>>(j, Utf16_Utf8<std::wstring, std::string>::convert(L"maybeChoice"));
        j.at("maybeKind");
        x.maybe_kind = get_stack_optional<MaybeKind>(j, Utf16_Utf8<std::wstring, std::string>::convert(L"maybeKind"));
        j.at("maybeRec");
        x.maybe_rec = get_heap_optional<MaybeRec>(j, Utf16_Utf8<std::wstring, std::string>::convert(L"maybeRec"));
        j.at("maybeSmall");
        x.maybe_small = get_stack_optional<int64_t>(j, Utf16_Utf8<std::wstring, std::string>::convert(L"maybeSmall"));
        x.mixed_map = Utf16_Utf8<std::map<std::string, MixedMap>, std::map<std::wstring, MixedMap>>::convert(j.at(Utf16_Utf8<std::wstring, std::string>::convert(L"mixedMap")).get<std::map<std::string, MixedMap>>());
        x.name = Utf16_Utf8<std::string, std::wstring>::convert(j.at(Utf16_Utf8<std::wstring, std::string>::convert(L"name")).get<std::string>());
        x.node = j.at(Utf16_Utf8<std::wstring, std::string>::convert(L"node")).get<Node>();
        x.nothing = get_untyped(j, Utf16_Utf8<std::wstring, std::string>::convert(L"nothing"));
        if (j.find(([] { constexpr auto &s = "nul\u0000key"; return std::string(s, sizeof(s) / sizeof(s[0]) - 1); }())) != j.end() && !j.at(([] { constexpr auto &s = "nul\u0000key"; return std::string(s, sizeof(s) / sizeof(s[0]) - 1); }())).is_number_integer()) throw std::runtime_error("Expected integer");
        x.nul_key = j.at(Utf16_Utf8<std::wstring, std::string>::convert(([] { constexpr auto &s = L"nul\u0000key"; return std::wstring(s, sizeof(s) / sizeof(s[0]) - 1); }()))).get<int64_t>();
        x.opt_anything = get_untyped(j, Utf16_Utf8<std::wstring, std::string>::convert(L"optAnything"));
        if (j.find("optName") != j.end() && j.at("optName").is_null()) throw std::runtime_error("Unexpected null");
        x.opt_name = Utf16_Utf8<std::optional<std::string>, std::optional<std::wstring>>::convert(get_stack_optional<std::string>(j, Utf16_Utf8<std::wstring, std::string>::convert(L"optName")));
        if (j.find("optNode") != j.end() && j.at("optNode").is_null()) throw std::runtime_error("Unexpected null");
        x.opt_node = get_heap_optional<Node>(j, Utf16_Utf8<std::wstring, std::string>::convert(L"optNode"));
        x.opt_nothing = get_untyped(j, Utf16_Utf8<std::wstring, std::string>::convert(L"optNothing"));
        if (j.find("optRec") != j.end() && j.at("optRec").is_null()) throw std::runtime_error("Unexpected null");
        x.opt_rec = get_heap_optional<Rec>(j, Utf16_Utf8<std::wstring, std::string>::convert(L"optRec"));
        if (j.find("optWhen") != j.end() && !std::regex_match(j.at("optWhen").get<std::string>(), std::regex("^[0-9]{4}-[0-9]{2}-[0-9]{2}T.*$"))) throw std::runtime_error("Expected date-time");
        if (j.find("optWhen") != j.end() && j.at("optWhen").is_null()) throw std::runtime_error("Unexpected null");
        x.opt_when = get_stack_optional<std::wstring>(j, Utf16_Utf8<std::wstring, std::string>::convert(L"optWhen"));
        x.ratio = j.at(Utf16_Utf8<std::wstring, std::string>::convert(L"ratio")).get<double>();
        x.rec = j.at(Utf16_Utf8<std::wstring, std::string>::convert(L"rec")).get<Rec>();
        if (j.find("small") != j.end() && !j.at("small").is_number_integer()) throw std::runtime_error("Expected integer");
        x.small = j.at(Utf16_Utf8<std::wstring, std::string>::convert(L"small")).get<int64_t>();
        if (j.at("tags").size() < 1) throw std::runtime_error("Too few items");
        if (j.at("tags").size() > 4) throw std::runtime_error("Too many items");
        x.tags = Utf16_Utf8<std::vector<std::string>, std::vector<std::wstring>>::convert(j.at(Utf16_Utf8<std::wstring, std::string>::convert(L"tags")).get<std::vector<std::string>>());
        if (j.find("when") != j.end() && !std::regex_match(j.at("when").get<std::string>(), std::regex("^[0-9]{4}-[0-9]{2}-[0-9]{2}T.*$"))) throw std::runtime_error("Expected date-time");
        x.when = j.at(Utf16_Utf8<std::wstring, std::string>::convert(L"when")).get<std::wstring>();
    }

