                break;
            case 1:
                j = boost::get<double>(x);
                break;
            case 2:
                j = boost::get<int64_t>(x);
                break;
            case 3:
                j = boost::get<std::string>(x);
                break;
            default: throw std::runtime_error("Input JSON does not conform to schema!");
