    inline void from_json(json const & j, Node& x) {
        if (!j.is_object()) throw std::runtime_error("Expected object");
        if (j.find("children") != j.end() && j.at("children").is_null()) throw std::runtime_error("Unexpected null");
        x.set_children(get_stack_optional<std::vector<Node>>(j, "children"));
        if (j.find("next") != j.end() && j.at("next").is_null()) throw std::runtime_error("Unexpected null");
        x.set_next(get_heap_optional<Node>(j, "next"));
        x.set_value(j.at("value").get<std::string>());
    }

    inline void to_json(json & j, Node const & x) {
        j = json::object();
        j["children"] = x.get_children();
        j["next"] = x.get_next();
        j["value"] = x.get_value();
    }

    inline void from_json(json const & j, TopLevel& x) {
        if (!j.is_object()) throw std::runtime_error("Expected object");
        x.set_anything(get_untyped(j, "anything"));
        x.set_big_kind(j.at("bigKind").get<BigKind>());
        x.set_choice(j.at("choice").get<ChoiceUnion>());
        x.set_counts(j.at("counts").get<std::map<std::string, int64_t>>());
        x.set_flag(j.at("flag").get<bool>());
        if (j.find("id") != j.end() && !std::regex_match(j.at("id").get<std::string>(), std::regex("^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$"))) throw std::runtime_error("Expected UUID");
        x.set_id(j.at("id").get<std::string>());
        x.set_kind(j.at("kind").get<Kind>());
        j.at("maybeChoice");
        x.set_maybe_choice(get_stack_optional<std::variant<int64_t, std::string>>(j, "maybeChoice"));
        j.at("maybeKind");
        x.set_maybe_kind(get_stack_optional<MaybeKind>(j, "maybeKind"));
        j.at("maybeRec");
        x.set_maybe_rec(get_heap_optional<MaybeRec>(j, "maybeRec"));
        j.at("maybeSmall");
        x.set_maybe_small(get_stack_optional<int64_t>(j, "maybeSmall"));
        x.set_mixed_map(j.at("mixedMap").get<std::map<std::string, MixedMap>>());
        x.set_name(j.at("name").get<std::string>());
        x.set_node(j.at("node").get<Node>());
        x.set_nothing(get_untyped(j, "nothing"));
        if (j.find(([] { constexpr auto &s = "nul\u0000key"; return std::string(s, sizeof(s) / sizeof(s[0]) - 1); }())) != j.end() && !j.at(([] { constexpr auto &s = "nul\u0000key"; return std::string(s, sizeof(s) / sizeof(s[0]) - 1); }())).is_number_integer()) throw std::runtime_error("Expected integer");
        x.set_nul_key(j.at(([] { constexpr auto &s = "nul\u0000key"; return std::string(s, sizeof(s) / sizeof(s[0]) - 1); }())).get<int64_t>());
        x.set_opt_anything(get_untyped(j, "optAnything"));
        if (j.find("optName") != j.end() && j.at("optName").is_null()) throw std::runtime_error("Unexpected null");
        x.set_opt_name(get_stack_optional<std::string>(j, "optName"));
        if (j.find("optNode") != j.end() && j.at("optNode").is_null()) throw std::runtime_error("Unexpected null");
        x.set_opt_node(get_heap_optional<Node>(j, "optNode"));
        x.set_opt_nothing(get_untyped(j, "optNothing"));
        if (j.find("optRec") != j.end() && j.at("optRec").is_null()) throw std::runtime_error("Unexpected null");
        x.set_opt_rec(get_heap_optional<Rec>(j, "optRec"));
        if (j.find("optWhen") != j.end() && !std::regex_match(j.at("optWhen").get<std::string>(), std::regex("^[0-9]{4}-[0-9]{2}-[0-9]{2}T.*$"))) throw std::runtime_error("Expected date-time");
        if (j.find("optWhen") != j.end() && j.at("optWhen").is_null()) throw std::runtime_error("Unexpected null");
        x.set_opt_when(get_stack_optional<std::string>(j, "optWhen"));
        x.set_ratio(j.at("ratio").get<double>());
        x.set_rec(j.at("rec").get<Rec>());
        if (j.find("small") != j.end() && !j.at("small").is_number_integer()) throw std::runtime_error("Expected integer");
        x.set_small(j.at("small").get<int64_t>());
        if (j.at("tags").size() < 1) throw std::runtime_error("Too few items");
        if (j.at("tags").size() > 4) throw std::runtime_error("Too many items");
        x.set_tags(j.at("tags").get<std::vector<std::string>>());
        if (j.find("when") != j.end() && !std::regex_match(j.at("when").get<std::string>(), std::regex("^[0-9]{4}-[0-9]{2}-[0-9]{2}T.*$"))) throw std::runtime_error("Expected date-time");
        x.set_when(j.at("when").get<std::string>());
    }

    inline void to_json(json & j, TopLevel const & x) {
        j = json::object();
        j["anything"] = x.get_anything();
        j["bigKind"] = x.get_big_kind();
        j["choice"] = x.get_choice();
        j["counts"] = x.get_counts();
        j["flag"] = x.get_flag();
        j["id"] = x.get_id();
        j["kind"] = x.get_kind();
        j["maybeChoice"] = x.get_maybe_choice();
        j["maybeKind"] = x.get_maybe_kind();
        j["maybeRec"] = x.get_maybe_rec();
        j["maybeSmall"] = x.get_maybe_small();
        j["mixedMap"] = x.get_mixed_map();
        j["name"] = x.get_name();
        j["node"] = x.get_node();
        j["nothing"] = x.get_nothing();
