        j["optNothing"] = x.get_opt_nothing();
        j["optRec"] = x.get_opt_rec();
        j["optWhen"] = x.get_opt_when();
        j["ratio"] = x.get_ratio();
        j["rec"] = x.get_rec();
        j["small"] = x.get_small();
        j["tags"] = x.get_tags();
        j["when"] = x.get_when();
    }

