    class classMemberConstraints {
        private:
        std::optional<int64_t> MinIntValue;
        std::optional<int64_t> MaxIntValue;
        std::optional<double> MinDoubleValue;
        std::optional<double> MaxDoubleValue;
        std::optional<size_t> MinLength;
        std::optional<size_t> MaxLength;
        std::optional<std::string> Pattern;

        public:
        classMemberConstraints(
            std::optional<int64_t> MinIntValue,
            std::optional<int64_t> MaxIntValue,
            std::optional<double> MinDoubleValue,
            std::optional<double> MaxDoubleValue,
            std::optional<size_t> MinLength,
            std::optional<size_t> MaxLength,
            std::optional<std::string> Pattern
        ) : MinIntValue(MinIntValue), MaxIntValue(MaxIntValue), MinDoubleValue(MinDoubleValue), MaxDoubleValue(MaxDoubleValue), MinLength(MinLength), MaxLength(MaxLength), Pattern(Pattern) {}
        classMemberConstraints() = default;
        virtual ~classMemberConstraints() = default;

        void SetMinIntValue(int64_t MinIntValue) { this->MinIntValue = MinIntValue; }
        auto GetMinIntValue() const { return MinIntValue; }

        void SetMaxIntValue(int64_t MaxIntValue) { this->MaxIntValue = MaxIntValue; }
        auto GetMaxIntValue() const { return MaxIntValue; }

        void SetMinDoubleValue(double MinDoubleValue) { this->MinDoubleValue = MinDoubleValue; }
        auto GetMinDoubleValue() const { return MinDoubleValue; }

        void SetMaxDoubleValue(double MaxDoubleValue) { this->MaxDoubleValue = MaxDoubleValue; }
        auto GetMaxDoubleValue() const { return MaxDoubleValue; }

        void SetMinLength(size_t MinLength) { this->MinLength = MinLength; }
        auto GetMinLength() const { return MinLength; }

        void SetMaxLength(size_t MaxLength) { this->MaxLength = MaxLength; }
        auto GetMaxLength() const { return MaxLength; }

        void SetPattern(const std::string &  Pattern) { this->Pattern = Pattern; }
        auto GetPattern() const { return Pattern; }
    };

    class classMemberConstraintException : public std::runtime_error {
        public:
        classMemberConstraintException(const std::string &  msg) : std::runtime_error(msg) {}
    };

    class valueTooLowException : public classMemberConstraintException {
        public:
        valueTooLowException(const std::string &  msg) : classMemberConstraintException(msg) {}
    };

    class valueTooHighException : public classMemberConstraintException {
        public:
        valueTooHighException(const std::string &  msg) : classMemberConstraintException(msg) {}
    };

    class valueTooShortException : public classMemberConstraintException {
        public:
        valueTooShortException(const std::string &  msg) : classMemberConstraintException(msg) {}
    };

    class valueTooLongException : public classMemberConstraintException {
        public:
        valueTooLongException(const std::string &  msg) : classMemberConstraintException(msg) {}
    };

    class invalidPatternException : public classMemberConstraintException {
        public:
        invalidPatternException(const std::string &  msg) : classMemberConstraintException(msg) {}
    };

    inline void checkConstraint(const std::string &  name, const classMemberConstraints & c, int64_t value) {
        if (c.GetMinIntValue() != std::nullopt && value < *c.GetMinIntValue()) {
            throw valueTooLowException ("Value too low for " + name + " (" + std::to_string(value) + "<" + std::to_string(*c.GetMinIntValue()) + ")");
        }

        if (c.GetMaxIntValue() != std::nullopt && value > *c.GetMaxIntValue()) {
            throw valueTooHighException ("Value too high for " + name + " (" + std::to_string(value) + ">" + std::to_string(*c.GetMaxIntValue()) + ")");
        }
    }

    inline void checkConstraint(const std::string &  name, const classMemberConstraints & c, const std::optional<int64_t> & value) {
        if (value) {
            checkConstraint(name, c, *value);
        }
    }

    inline void checkConstraint(const std::string &  name, const classMemberConstraints & c, double value) {
        if (c.GetMinDoubleValue() != std::nullopt && value < *c.GetMinDoubleValue()) {
            throw valueTooLowException ("Value too low for " + name + " (" + std::to_string(value) + "<" + std::to_string(*c.GetMinDoubleValue()) + ")");
        }

        if (c.GetMaxDoubleValue() != std::nullopt && value > *c.GetMaxDoubleValue()) {
            throw valueTooHighException ("Value too high for " + name + " (" + std::to_string(value) + ">" + std::to_string(*c.GetMaxDoubleValue()) + ")");
        }
    }

    inline void checkConstraint(const std::string &  name, const classMemberConstraints & c, const std::optional<double> & value) {
        if (value) {
            checkConstraint(name, c, *value);
        }
    }

    inline size_t codePointLength(const std::string &  value) {
        return std::count_if(value.begin(), value.end(), [](char ch) { return (static_cast<unsigned char>(ch) & 0xC0) != 0x80; });
    }

    inline void checkConstraint(const std::string &  name, const classMemberConstraints & c, const std::string &  value) {
        if (c.GetMinLength() != std::nullopt && codePointLength(value) < *c.GetMinLength()) {
            throw valueTooShortException ("Value too short for " + name + " (" + std::to_string(codePointLength(value)) + "<" + std::to_string(*c.GetMinLength()) + ")");
        }

        if (c.GetMaxLength() != std::nullopt && codePointLength(value) > *c.GetMaxLength()) {
            throw valueTooLongException ("Value too long for " + name + " (" + std::to_string(codePointLength(value)) + ">" + std::to_string(*c.GetMaxLength()) + ")");
        }

        if (c.GetPattern() != std::nullopt) {
            std::smatch result;
            std::regex_search(value, result, std::regex( *c.GetPattern() ));
            if (result.empty()) {
                throw invalidPatternException ("Value doesn't match pattern for " + name + " (" + value +" != " + *c.GetPattern() + ")");
            }
        }
    }

    inline void checkConstraint(const std::string &  name, const classMemberConstraints & c, const std::optional<std::string> & value) {
        if (value) {
            checkConstraint(name, c, *value);
        }
    }

