        x.SetMixedMap(j.at("mixedMap").get<std::map<std::string, mixedMap>>());
        x.SetName(j.at("name").get<std::string>());
        x.SetNode(j.at("node").get<node>());
        x.SetNothing(get_untyped(j, "nothing"));
        if (j.find(([] { constexpr auto &s = "nul\u0000key"; return std::string(s, sizeof(s) / sizeof(s[0]) - 1); }())) != j.end() && !j.at(([] { constexpr auto &s = "nul\u0000key"; return std::string(s, sizeof(s) / sizeof(s[0]) - 1); }())).is_number_integer()) throw std::runtime_error("Expected integer");
        x.SetNulKey(j.at(([] { constexpr auto &s = "nul\u0000key"; return std::string(s, sizeof(s) / sizeof(s[0]) - 1); }())).get<int64_t>());
