    using nlohmann::json;

    class class_member_constraints {
        private:
        std::optional<int64_t> MinIntValue;
        std::optional<int64_t> MaxIntValue;
        std::optional<double> MinDoubleValue;
        std::optional<double> MaxDoubleValue;
        std::optional<size_t> MinLength;
        std::optional<size_t> MaxLength;
        std::optional<std::string> Pattern;

        public:
        class_member_constraints(
            std::optional<int64_t> MinIntValue,
            std::optional<int64_t> MaxIntValue,
            std::optional<double> MinDoubleValue,
            std::optional<double> MaxDoubleValue,
            std::optional<size_t> MinLength,
            std::optional<size_t> MaxLength,
            std::optional<std::string> Pattern
        ) : MinIntValue(MinIntValue), MaxIntValue(MaxIntValue), MinDoubleValue(MinDoubleValue), MaxDoubleValue(MaxDoubleValue), MinLength(MinLength), MaxLength(MaxLength), Pattern(Pattern) {}
        class_member_constraints() = default;
        virtual ~class_member_constraints() = default;

        void SetMinIntValue(int64_t MinIntValue) { this->MinIntValue = MinIntValue; }
        auto GetMinIntValue() const { return MinIntValue; }

        void SetMaxIntValue(int64_t MaxIntValue) { this->MaxIntValue = MaxIntValue; }
        auto GetMaxIntValue() const { return MaxIntValue; }

        void SetMinDoubleValue(double MinDoubleValue) { this->MinDoubleValue = MinDoubleValue; }
        auto GetMinDoubleValue() const { return MinDoubleValue; }

        void SetMaxDoubleValue(double MaxDoubleValue) { this->MaxDoubleValue = MaxDoubleValue; }
        auto GetMaxDoubleValue() const { return MaxDoubleValue; }

        void SetMinLength(size_t MinLength) { this->MinLength = MinLength; }
        auto GetMinLength() const { return MinLength; }

        void SetMaxLength(size_t MaxLength) { this->MaxLength = MaxLength; }
        auto GetMaxLength() const { return MaxLength; }

        void SetPattern(const std::string &  Pattern) { this->Pattern = Pattern; }
        auto GetPattern() const { return Pattern; }
    };

    class class_member_constraint_exception : public std::runtime_error {
        public:
        class_member_constraint_exception(const std::string &  msg) : std::runtime_error(msg) {}
    };

    class value_too_low_exception : public class_member_constraint_exception {
        public:
        value_too_low_exception(const std::string &  msg) : class_member_constraint_exception(msg) {}
    };

    class value_too_high_exception : public class_member_constraint_exception {
        public:
        value_too_high_exception(const std::string &  msg) : class_member_constraint_exception(msg) {}
    };

    class value_too_short_exception : public class_member_constraint_exception {
        public:
        value_too_short_exception(const std::string &  msg) : class_member_constraint_exception(msg) {}
    };

    class value_too_long_exception : public class_member_constraint_exception {
        public:
        value_too_long_exception(const std::string &  msg) : class_member_constraint_exception(msg) {}
    };

    class invalid_pattern_exception : public class_member_constraint_exception {
        public:
        invalid_pattern_exception(const std::string &  msg) : class_member_constraint_exception(msg) {}
    };

    inline void check_constraint(const std::string &  name, const class_member_constraints & c, int64_t value) {
        if (c.GetMinIntValue() != std::nullopt && value < *c.GetMinIntValue()) {
            throw value_too_low_exception ("Value too low for " + name + " (" + std::to_string(value) + "<" + std::to_string(*c.GetMinIntValue()) + ")");
        }

        if (c.GetMaxIntValue() != std::nullopt && value > *c.GetMaxIntValue()) {
            throw value_too_high_exception ("Value too high for " + name + " (" + std::to_string(value) + ">" + std::to_string(*c.GetMaxIntValue()) + ")");
        }
    }

    inline void check_constraint(const std::string &  name, const class_member_constraints & c, const std::optional<int64_t> & value) {
        if (value) {
            check_constraint(name, c, *value);
        }
    }

    inline void check_constraint(const std::string &  name, const class_member_constraints & c, double value) {
        if (c.GetMinDoubleValue() != std::nullopt && value < *c.GetMinDoubleValue()) {
            throw value_too_low_exception ("Value too low for " + name + " (" + std::to_string(value) + "<" + std::to_string(*c.GetMinDoubleValue()) + ")");
        }

        if (c.GetMaxDoubleValue() != std::nullopt && value > *c.GetMaxDoubleValue()) {
            throw value_too_high_exception ("Value too high for " + name + " (" + std::to_string(value) + ">" + std::to_string(*c.GetMaxDoubleValue()) + ")");
        }
    }

    inline void check_constraint(const std::string &  name, const class_member_constraints & c, const std::optional<double> & value) {
        if (value) {
            check_constraint(name, c, *value);
        }
    }

    inline size_t code_point_length(const std::string &  value) {
        return std::count_if(value.begin(), value.end(), [](char ch) { return (static_cast<unsigned char>(ch) & 0xC0) != 0x80; });
    }

    inline void check_constraint(const std::string &  name, const class_member_constraints & c, const std::string &  value) {
        if (c.GetMinLength() != std::nullopt && code_point_length(value) < *c.GetMinLength()) {
            throw value_too_short_exception ("Value too short for " + name + " (" + std::to_string(code_point_length(value)) + "<" + std::to_string(*c.GetMinLength()) + ")");
        }

        if (c.GetMaxLength() != std::nullopt && code_point_length(value) > *c.GetMaxLength()) {
            throw value_too_long_exception ("Value too long for " + name + " (" + std::to_string(code_point_length(value)) + ">" + std::to_string(*c.GetMaxLength()) + ")");
        }

        if (c.GetPattern() != std::nullopt) {
            std::smatch result;
            std::regex_search(value, result, std::regex( *c.GetPattern() ));
            if (result.empty()) {
                throw invalid_pattern_exception ("Value doesn't match pattern for " + name + " (" + value +" != " + *c.GetPattern() + ")");
            }
        }
    }

    inline void check_constraint(const std::string &  name, const class_member_constraints & c, const std::optional<std::string> & value) {
        if (value) {
            check_constraint(name, c, *value);
        }
    }

